-- Squashed initial migration (coauth).
-- Final schema as of 2026-06-10, consolidated from the previous migration chain
-- (generated by applying all historical migrations and dumping the resulting schema).

CREATE FUNCTION public.handle_audit_log_block_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'handle_audit_log is append-only; % is not permitted', TG_OP;
END;
$$;

CREATE TABLE public.account_claims (
    id uuid NOT NULL,
    account_id uuid,
    claim_kind text NOT NULL,
    subject text NOT NULL,
    issuer text NOT NULL,
    verifier_did text NOT NULL,
    represented_organization text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    revoked_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_claims_claim_kind_non_empty CHECK ((btrim(claim_kind) <> ''::text)),
    CONSTRAINT account_claims_issuer_non_empty CHECK ((btrim(issuer) <> ''::text)),
    CONSTRAINT account_claims_represented_organization_non_empty CHECK ((btrim(represented_organization) <> ''::text)),
    CONSTRAINT account_claims_subject_non_empty CHECK ((btrim(subject) <> ''::text)),
    CONSTRAINT account_claims_verifier_did_non_empty CHECK ((btrim(verifier_did) <> ''::text))
);

-- Full-hash collision evidence for Agent authorization Events. Rows are
-- append-only variants; the parent authorization is unusable while
-- quarantined, and neither variant is selected as authoritative by hash.
CREATE TABLE public.agent_key_authorization_collision_variants (
    id uuid NOT NULL,
    authorized_event_id text NOT NULL,
    canonical_preimage bytea NOT NULL,
    envelope jsonb NOT NULL,
    observed_at timestamp with time zone NOT NULL
);

CREATE TABLE public.account_security_events (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    event_type text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    ip_address inet,
    user_agent text,
    created_at timestamp with time zone NOT NULL
);

CREATE TABLE public.accountability_grants (
    id uuid NOT NULL,
    accountability_grant_id text NOT NULL,
    agent_id text NOT NULL,
    controller_id text NOT NULL,
    capabilities text[] NOT NULL,
    capabilities_digest text NOT NULL,
    reason text,
    issued_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    raw_payload_digest text NOT NULL,
    soland_fanout_state text NOT NULL,
    soland_fanout_idempotency_key text NOT NULL,
    soland_fanout_payload jsonb NOT NULL,
    soland_fanout_attempt integer DEFAULT 0 NOT NULL,
    soland_fanout_next_retry_at timestamp with time zone,
    soland_fanout_dead_letter_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.accountability_subject_revocations (
    id uuid NOT NULL,
    subject_kind text NOT NULL,
    subject_id text NOT NULL,
    reason text NOT NULL,
    revoked_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

-- AKP-0008 §4.5: durable accepted agent key authorizations. Column order
-- tracks event-payload.schema.json#/$defs/agent_key_authorize_payload
-- (agent_id, key_id, verification_method, accountable_principal_id,
-- audience, issued_at, expires_at) so the fan-out payload soland writes as
-- `ak.agent.key.authorize` stays field-aligned with the spec. `expires_at`
-- is NULLable: absent means the authorization never expires by time and is
-- governed solely by the revocation chain (key-management §3.6.1).
CREATE TABLE public.agent_key_authorizations (
    id uuid NOT NULL,
    authorized_event_id text NOT NULL,
    agent_id text NOT NULL,
    key_id text NOT NULL,
    verification_method text NOT NULL,
    public_key jsonb NOT NULL,
    accountable_principal_id text NOT NULL,
    agent_key_scope text NOT NULL,
    audience text[] NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    pairing_request_id text NOT NULL,
    request_canonical_digest text NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    quarantined_at timestamp with time zone,
    quarantine_reason text,
    raw_payload_digest text NOT NULL,
    soland_fanout_state text NOT NULL,
    soland_fanout_idempotency_key text NOT NULL,
    soland_fanout_payload jsonb NOT NULL,
    soland_fanout_attempt integer DEFAULT 0 NOT NULL,
    soland_fanout_next_retry_at timestamp with time zone,
    soland_fanout_dead_letter_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

-- AKP-0008 §4.6: single-consumption replay table for agent_key_proof session
-- grants. Each accepted proof challenge and nonce is consumed exactly once;
-- rows survive past the proof `expires_at` by a grace window so a replay
-- inside the window is still rejected. A sweeper prunes rows past `prune_after`.
CREATE TABLE public.agent_session_proof_replay (
    id uuid NOT NULL,
    agent_id text NOT NULL,
    verification_method text NOT NULL,
    challenge text NOT NULL,
    nonce text NOT NULL,
    request_canonical_digest text NOT NULL,
    audience_id text NOT NULL,
    consumed_at timestamp with time zone NOT NULL,
    proof_expires_at timestamp with time zone NOT NULL,
    prune_after timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL
);

-- Accepted DID bindings (`did-usage-and-verification.md` §5). One row is one
-- acceptance: a verified binding plus the DID document it pins, stored in
-- `accepted` as the canonical serialization of the shared SDK value object.
--
-- The primary key is the full six-dimension store key. `verification_method`
-- and `version_id` are optional dimensions, but a PostgreSQL primary key
-- cannot contain NULL, so "absent" is encoded as the empty string — neither a
-- DID URL nor a method version identifier can be empty, so this is
-- unambiguous.
--
-- `history_head` is not a key dimension but *is* a §5 invalidation dimension
-- (witness fork), so it gets its own index. `expires_at` bounds how long an
-- acceptance is readable; expired rows are filtered out on read and dropped
-- on the next write (see `dpop_jti_replay` for the same lazy-prune pattern).
CREATE TABLE public.verified_did_bindings (
    did text NOT NULL,
    trust_domain text NOT NULL,
    purpose text NOT NULL,
    policy_digest text NOT NULL,
    verification_method text NOT NULL,
    history_head text,
    expires_at timestamp with time zone,
    accepted jsonb NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.account_status_ledger_heads (
    account_authority_id text NOT NULL,
    local_account_id text NOT NULL,
    current_status_seq bigint,
    current_record_id text,
    PRIMARY KEY (account_authority_id, local_account_id),
    CHECK ((current_status_seq IS NULL) = (current_record_id IS NULL))
);

CREATE TABLE public.account_status_records (
    account_authority_id text NOT NULL,
    local_account_id text NOT NULL,
    status_seq bigint NOT NULL CHECK (status_seq >= 1),
    record_id text NOT NULL,
    record jsonb NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    PRIMARY KEY (account_authority_id, local_account_id, status_seq),
    UNIQUE (record_id)
);

CREATE INDEX account_status_records_range_idx
    ON public.account_status_records (account_authority_id, local_account_id, status_seq);

-- RFC 9449 DPoP proof replay cache. `jti_digest` is a SHA-256 digest of
-- the caller-supplied `jti`, bounded for storage and safe for audit logs.
CREATE TABLE public.dpop_jti_replay (
    jti_digest text NOT NULL,
    seen_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL
);

-- Durable self-service erasure intents
-- (`ak.gate.account.command.request_erasure.v1`, account-lifecycle.md §8.1).
-- One row per accepted request_id; `canonical_outcome` carries the exact
-- acceptance bytes for byte-identical replays, and the partial unique index
-- below enforces at most one live (record not yet signed) intent per user.
CREATE TABLE public.user_erasure_requests (
    request_id text NOT NULL,
    user_id uuid NOT NULL,
    request_digest text NOT NULL,
    canonical_outcome bytea NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    withdrawal_window_ends_at timestamp with time zone,
    record_issued_at timestamp with time zone,
    account_status_record_id text,
    PRIMARY KEY (request_id)
);

CREATE UNIQUE INDEX user_erasure_requests_live_intent_idx
    ON public.user_erasure_requests (user_id) WHERE record_issued_at IS NULL;

CREATE TABLE public.recovery_completion_grant_issuances (
    transaction_id text NOT NULL,
    transaction_request_digest text NOT NULL,
    local_account_id uuid NOT NULL,
    principal_id text NOT NULL,
    device_id text NOT NULL,
    device_authorization_event_id text NOT NULL,
    result_model_generation_ref jsonb NOT NULL,
    canonical_request_digest text NOT NULL,
    canonical_request bytea NOT NULL,
    session_grant_operation_id uuid NOT NULL,
    canonical_outcome bytea NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    CONSTRAINT recovery_completion_grant_issuances_principal_core_valid CHECK (principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$')
);

CREATE TABLE public.admin_operation_logs (
    id uuid NOT NULL,
    admin_user_id uuid NOT NULL,
