    CONSTRAINT oauth_client_localized_metadata_field_check CHECK ((field = ANY (ARRAY['client_name'::text, 'logo_uri'::text, 'client_uri'::text, 'policy_uri'::text, 'tos_uri'::text])))
);

CREATE TABLE public.oauth_clients (
