    chain_created_at timestamp with time zone NOT NULL,
    last_seen_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL
);

CREATE TABLE public.oauth_session_grant_operations (
    id uuid NOT NULL,
    issuer_id text NOT NULL,
    operation_kind text NOT NULL,
    proof_kind text,
    request_identity text NOT NULL,
    canonical_intent_digest bytea NOT NULL,
    canonical_intent bytea,
    operation_selector jsonb,
    issuance_nonce text,
    session_id text,
    grant_not_before timestamp with time zone,
    grant_expires_at timestamp with time zone,
    signing_key_id text,
    state text NOT NULL,
    proof_authorization_ref text,
    proof_authorization_checkpoint jsonb,
    proof_expires_at timestamp with time zone,
    outcome_digest bytea,
    canonical_outcome bytea,
    target_session_grant_id bytea,
    result_grant_id bytea,
    affected_grant_ids bytea[] DEFAULT '{}'::bytea[] NOT NULL,
    retained_until timestamp with time zone NOT NULL,
    committed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT oauth_session_grant_operations_issuer_id_nonempty CHECK ((btrim(issuer_id) <> ''::text)),
    CONSTRAINT oauth_session_grant_operations_request_identity_nonempty CHECK ((btrim(request_identity) <> ''::text)),
    CONSTRAINT oauth_session_grant_operations_kind_valid CHECK ((operation_kind = ANY (ARRAY['issue'::text, 'refresh'::text, 'revoke'::text]))),
    CONSTRAINT oauth_session_grant_operations_proof_kind_shape CHECK ((((operation_kind = 'issue'::text) AND (proof_kind IS NOT NULL)) OR ((operation_kind <> 'issue'::text) AND (proof_kind IS NULL)))),
    CONSTRAINT oauth_session_grant_operations_digest_length CHECK ((octet_length(canonical_intent_digest) = 32)),
    CONSTRAINT oauth_session_grant_operations_seed_shape CHECK (((state = 'evicted'::text) AND (issuance_nonce IS NULL) AND (session_id IS NULL) AND (grant_not_before IS NULL) AND (grant_expires_at IS NULL) AND (signing_key_id IS NULL)) OR ((state <> 'evicted'::text) AND (((operation_kind = 'revoke'::text) AND (issuance_nonce IS NULL) AND (session_id IS NULL) AND (grant_not_before IS NULL) AND (grant_expires_at IS NULL) AND (signing_key_id IS NULL)) OR ((operation_kind <> 'revoke'::text) AND (issuance_nonce ~ '^[A-Za-z0-9_-]{43}$'::text) AND (btrim(session_id) <> ''::text) AND (grant_expires_at > grant_not_before) AND (btrim(signing_key_id) <> ''::text))))),
    CONSTRAINT oauth_session_grant_operations_outcome_digest_length CHECK (((outcome_digest IS NULL) OR (octet_length(outcome_digest) = 32))),
    CONSTRAINT oauth_session_grant_operations_grant_id_lengths CHECK ((((target_session_grant_id IS NULL) OR (octet_length(target_session_grant_id) = 33)) AND ((result_grant_id IS NULL) OR (octet_length(result_grant_id) = 33)))),
    CONSTRAINT oauth_session_grant_operations_state_valid CHECK ((state = ANY (ARRAY['reserved'::text, 'authorized'::text, 'committed'::text, 'evicted'::text]))),
    CONSTRAINT oauth_session_grant_operations_retention_valid CHECK ((retained_until > created_at)),
    CONSTRAINT oauth_session_grant_operations_authorization_shape CHECK ((((state = 'reserved'::text) AND (proof_authorization_ref IS NULL) AND (proof_authorization_checkpoint IS NULL) AND (proof_expires_at IS NULL)) OR ((state = ANY (ARRAY['authorized'::text, 'committed'::text])) AND (proof_authorization_ref IS NOT NULL) AND (proof_authorization_checkpoint IS NOT NULL) AND (proof_expires_at IS NOT NULL) AND (retained_until >= proof_expires_at)) OR ((state = 'evicted'::text) AND (proof_authorization_ref IS NULL) AND (proof_authorization_checkpoint IS NULL) AND (proof_expires_at IS NULL)))),
    CONSTRAINT oauth_session_grant_operations_outcome_shape CHECK ((((state = ANY (ARRAY['reserved'::text, 'authorized'::text])) AND (result_grant_id IS NULL) AND (cardinality(affected_grant_ids) = 0) AND (outcome_digest IS NULL) AND (canonical_outcome IS NULL) AND (committed_at IS NULL)) OR ((state = 'committed'::text) AND (outcome_digest IS NOT NULL) AND (canonical_outcome IS NOT NULL) AND (committed_at IS NOT NULL) AND (((operation_kind = 'issue'::text) AND (target_session_grant_id IS NULL) AND (result_grant_id IS NOT NULL) AND (cardinality(affected_grant_ids) = 0)) OR ((operation_kind = 'refresh'::text) AND (target_session_grant_id IS NOT NULL) AND (result_grant_id IS NOT NULL) AND (cardinality(affected_grant_ids) = 0)) OR ((operation_kind = 'revoke'::text) AND (result_grant_id IS NULL)))) OR ((state = 'evicted'::text) AND (canonical_intent IS NULL) AND (operation_selector IS NULL) AND (proof_authorization_ref IS NULL) AND (proof_authorization_checkpoint IS NULL) AND (proof_expires_at IS NULL) AND (outcome_digest IS NULL) AND (canonical_outcome IS NULL))))
);

CREATE TABLE public.oauth_session_grants (
    id uuid NOT NULL,
    grant_id bytea NOT NULL CHECK ((octet_length(grant_id) = 33) AND (get_byte(grant_id, 0) = 1)),
    issuance_operation_id uuid NOT NULL,
    user_session_id uuid,
    issuer_id text NOT NULL,
    subject_id text NOT NULL,
    local_account_id text NOT NULL,
    device_id text,
    applet_id text,
    effective_scope jsonb,
    registration_epoch text,
    service_id text,
    capability_grant_refs text[] DEFAULT '{}'::text[] NOT NULL,
    audience_id text NOT NULL,
    scope_list text[] NOT NULL,
    grant_jwt text NOT NULL,
    session_id text NOT NULL,
    issuance_nonce text NOT NULL,
    issuance_preimage bytea NOT NULL,
    issuance_digest bytea NOT NULL,
    signing_key_id text NOT NULL,
    session_public_key text NOT NULL,
    credential_class text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    lifecycle_state text NOT NULL,
    revoked_at timestamp with time zone,
    superseded_at timestamp with time zone,
    successor_grant_id bytea,
    created_at timestamp with time zone NOT NULL
    ,CONSTRAINT oauth_session_grants_issuance_digest_valid CHECK ((octet_length(issuance_digest) = 32) AND (substring(grant_id from 2 for 32) = issuance_digest))
    ,CONSTRAINT oauth_session_grants_nonce_valid CHECK ((issuance_nonce ~ '^[A-Za-z0-9_-]{43}$'::text))
    ,CONSTRAINT oauth_session_grants_session_id_nonempty CHECK ((btrim(session_id) <> ''::text))
    ,CONSTRAINT oauth_session_grants_local_account_id_valid CHECK ((btrim(local_account_id) <> ''::text) AND (length(local_account_id) <= 255) AND (local_account_id !~ '^(ak|did):'::text))
    ,CONSTRAINT oauth_session_grants_signing_key_id_nonempty CHECK ((btrim(signing_key_id) <> ''::text))
    ,CONSTRAINT oauth_session_grants_lifecycle_valid CHECK ((lifecycle_state = ANY (ARRAY['active'::text, 'revoked'::text, 'superseded'::text])) AND (((lifecycle_state = 'active'::text) AND (revoked_at IS NULL) AND (superseded_at IS NULL) AND (successor_grant_id IS NULL)) OR ((lifecycle_state = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (superseded_at IS NULL) AND (successor_grant_id IS NULL)) OR ((lifecycle_state = 'superseded'::text) AND (revoked_at IS NULL) AND (superseded_at IS NOT NULL) AND (successor_grant_id IS NOT NULL))))
    ,CONSTRAINT oauth_session_grants_successor_id_valid CHECK (((successor_grant_id IS NULL) OR ((octet_length(successor_grant_id) = 33) AND (get_byte(successor_grant_id, 0) = 1))))
    ,CONSTRAINT oauth_session_grants_expiry_valid CHECK ((expires_at > created_at))
);

CREATE TABLE public.oauth_sessions (
    id uuid NOT NULL,
    user_session_id uuid,
    oauth_client_id uuid NOT NULL,
    user_id uuid NOT NULL,
    scope_list text[] NOT NULL,
    finished_at timestamp with time zone,
    user_agent text,
    last_active_at timestamp with time zone,
    last_active_ip inet,
    human_name text,
    created_at timestamp with time zone NOT NULL
);

CREATE TABLE public.personal_access_tokens (
    id uuid NOT NULL,
    personal_session_id uuid NOT NULL,
    access_token_sha256 bytea NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT personal_access_tokens_access_token_sha256_check CHECK ((length(access_token_sha256) = 32))
);

CREATE TABLE public.personal_sessions (
    id uuid NOT NULL,
    owner_user_id uuid,
    owner_oauth_client_id uuid,
    actor_user_id uuid NOT NULL,
    human_name text NOT NULL,
    scope_list text[] NOT NULL,
    revoked_at timestamp with time zone,
    last_active_at timestamp with time zone,
    last_active_ip inet,
    created_at timestamp with time zone NOT NULL
);

CREATE TABLE public.policy_data (
    id uuid NOT NULL,
    data jsonb NOT NULL,
    created_at timestamp with time zone NOT NULL
);

CREATE TABLE public.principal_did_owners (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    principal_id text NOT NULL,
    key_log_head text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.principal_did_bindings (
    id uuid NOT NULL,
    principal_did_owner_id uuid NOT NULL,
    user_id uuid NOT NULL,
    audience_id text NOT NULL,
    verified_did text NOT NULL,
    verified_version_id text NOT NULL,
    binding_receipt jsonb NOT NULL,
    accepted_id text NOT NULL,
    binding_version bigint NOT NULL,
    binding_frontier_digest text NOT NULL,
    account_id jsonb NOT NULL,
    principal_control_realm_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
    ,CONSTRAINT principal_did_binding_basis_shape CHECK (audience_id = accepted_id AND audience_id LIKE 'ak:did_core:%' AND binding_version >= 1 AND binding_frontier_digest ~ '^sha256:[0-9a-f]{64}$'::text AND principal_control_realm_id LIKE 'ak:realm:%')
    ,CONSTRAINT principal_did_binding_resolution_snapshot_shape CHECK (verified_did ~ '^did:[a-z0-9]+:[^[:space:]/?#]+$'::text AND btrim(verified_version_id) <> ''::text AND jsonb_typeof(binding_receipt) = 'object'::text AND jsonb_typeof(account_id) = 'object'::text)
);

-- Durable exact-replay ledger for short-lived Account Authority controller
-- lifecycle gate attestations. A reserved row without canonical_outcome is an
-- indeterminate issuance fence and is never re-signed on retry.
CREATE TABLE public.controller_gate_attestation_issuances (
    request_id uuid PRIMARY KEY,
    canonical_intent_digest text NOT NULL,
    principal_id text NOT NULL,
    agent_authority_id text NOT NULL,
    canonical_outcome bytea,
    outcome_digest text,
    attestation_expires_at timestamp with time zone,
    retained_until timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    committed_at timestamp with time zone,
    CONSTRAINT controller_gate_principal_core_valid CHECK (principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$'),
    CONSTRAINT controller_gate_intent_digest_valid CHECK (canonical_intent_digest ~ '^sha256:[0-9a-f]{64}$'),
    CONSTRAINT controller_gate_outcome_shape CHECK ((canonical_outcome IS NULL AND outcome_digest IS NULL AND attestation_expires_at IS NULL AND committed_at IS NULL) OR (canonical_outcome IS NOT NULL AND outcome_digest ~ '^sha256:[0-9a-f]{64}$' AND attestation_expires_at IS NOT NULL AND committed_at IS NOT NULL)),
    CONSTRAINT controller_gate_retention_valid CHECK (retained_until > created_at)
);

CREATE TABLE public.account_handoff_creation_attempts (
    request_id uuid NOT NULL,
    request_digest text NOT NULL,
    canonical_intent_digest text NOT NULL,
    canonical_intent bytea NOT NULL,
    holder_jkt text NOT NULL,
    issuer text NOT NULL,
    client_id text NOT NULL,
    authorization_code_digest text NOT NULL,
    dpop_jti_digest text NOT NULL,
    state text NOT NULL,
    authorization_checkpoint jsonb,
    canonical_outcome bytea,
    outcome_digest text,
    retained_until timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    authorized_at timestamp with time zone,
    committed_at timestamp with time zone,
    CONSTRAINT account_handoff_creation_attempts_request_digest_valid CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT account_handoff_creation_attempts_intent_digest_valid CHECK ((canonical_intent_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT account_handoff_creation_attempts_code_digest_valid CHECK ((authorization_code_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT account_handoff_creation_attempts_jti_digest_valid CHECK ((dpop_jti_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT account_handoff_creation_attempts_holder_jkt_valid CHECK ((holder_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT account_handoff_creation_attempts_state_closed CHECK ((state = ANY (ARRAY['reserved'::text, 'authorized'::text, 'committed'::text]))),
    CONSTRAINT account_handoff_creation_attempts_outcome_digest_valid CHECK (((outcome_digest IS NULL) OR (outcome_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT account_handoff_creation_attempts_state_shape CHECK (((state = 'reserved'::text AND authorization_checkpoint IS NULL AND canonical_outcome IS NULL AND outcome_digest IS NULL AND authorized_at IS NULL AND committed_at IS NULL) OR (state = 'authorized'::text AND authorization_checkpoint IS NOT NULL AND canonical_outcome IS NULL AND outcome_digest IS NULL AND authorized_at IS NOT NULL AND committed_at IS NULL) OR (state = 'committed'::text AND authorization_checkpoint IS NOT NULL AND canonical_outcome IS NOT NULL AND outcome_digest IS NOT NULL AND authorized_at IS NOT NULL AND committed_at IS NOT NULL))),
    CONSTRAINT account_handoff_creation_attempts_retention_valid CHECK ((retained_until > created_at))
);

CREATE TABLE public.account_handoff_grants (
    id uuid NOT NULL,
    request_id uuid NOT NULL,
    request_digest text NOT NULL,
    local_account_id uuid NOT NULL,
    browser_session_id uuid,
    audience_id text NOT NULL,
    cnf_jkt text NOT NULL,
    allowed_operations text[] NOT NULL,
    account_handoff_grant text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    consumed_at timestamp with time zone,
    CONSTRAINT account_handoff_grants_request_digest_valid CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT account_handoff_grants_audience_id_nonempty CHECK ((btrim(audience_id) <> ''::text)),
    CONSTRAINT account_handoff_grants_cnf_jkt_valid CHECK ((cnf_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT account_handoff_grants_allowed_operations_closed CHECK ((allowed_operations = ARRAY['ak.gate.account.command.issue_did_binding_challenge.v1'::text, 'ak.gate.account.command.issue_identity_binding_challenge.v1'::text, 'ak.gate.account.command.issue_identity_abandonment_challenge.v1'::text, 'ak.gate.account.command.abandon_identity_creation.v1'::text, 'ak.gate.account.command.register.v1'::text, 'ak.gate.account.command.issue_session_grant.v1'::text, 'ak.gate.account.command.issue_recovery_completion_grant.v1'::text])),
    CONSTRAINT account_handoff_grants_token_nonempty CHECK ((length(account_handoff_grant) >= 32)),
    CONSTRAINT account_handoff_grants_expiry_valid CHECK ((expires_at > issued_at))
);

CREATE TABLE public.identity_creation_leases (
    local_account_id uuid NOT NULL,
    audience_id text NOT NULL,
    lease_id text NOT NULL,
    holder_jkt text NOT NULL,
    fence bigint NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    reserved_principal_id text,
    reserved_operation_digest text,
    did_operation jsonb,
    registration_did_evidence jsonb,
    state text NOT NULL,
    registry_receipt jsonb,
    head_event_digest text,
    pcr_genesis_request_digest text,
    pcr_genesis_receipt jsonb,
    binding_receipt jsonb,
    register_handoff_grant_id uuid,
    register_challenge_id text,
    register_request_digest text,
    register_outcome jsonb,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT identity_creation_leases_audience_id_nonempty CHECK ((btrim(audience_id) <> ''::text)),
    CONSTRAINT identity_creation_leases_lease_id_valid CHECK ((lease_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_creation_leases_holder_jkt_valid CHECK ((holder_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT identity_creation_leases_fence_positive CHECK ((fence >= 1)),
    CONSTRAINT identity_creation_leases_operation_digest_valid CHECK (((reserved_operation_digest IS NULL) OR (reserved_operation_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT identity_creation_leases_registration_evidence_object CHECK (((registration_did_evidence IS NULL) OR (jsonb_typeof(registration_did_evidence) = 'object'::text))),
    CONSTRAINT identity_creation_leases_head_digest_valid CHECK (((head_event_digest IS NULL) OR (head_event_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT identity_creation_leases_pcr_request_digest_valid CHECK (((pcr_genesis_request_digest IS NULL) OR (pcr_genesis_request_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT identity_creation_leases_pcr_receipt_object CHECK (((pcr_genesis_receipt IS NULL) OR (jsonb_typeof(pcr_genesis_receipt) = 'object'::text))),
    CONSTRAINT identity_creation_leases_register_challenge_id_valid CHECK (((register_challenge_id IS NULL) OR (register_challenge_id ~ '^[A-Za-z0-9_-]{22,128}$'::text))),
    CONSTRAINT identity_creation_leases_register_request_digest_valid CHECK (((register_request_digest IS NULL) OR (register_request_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT identity_creation_leases_register_outcome_object CHECK (((register_outcome IS NULL) OR (jsonb_typeof(register_outcome) = 'object'::text))),
    CONSTRAINT identity_creation_leases_state_valid CHECK ((state = ANY (ARRAY['active'::text, 'reserved'::text, 'did_published'::text, 'pcr_accepted'::text, 'account_bound'::text, 'completed'::text]))),
    CONSTRAINT identity_creation_leases_reservation_complete CHECK ((((state = 'active'::text) AND (reserved_principal_id IS NULL) AND (reserved_operation_digest IS NULL) AND (did_operation IS NULL)) OR ((state <> 'active'::text) AND (reserved_principal_id IS NOT NULL) AND (reserved_operation_digest IS NOT NULL) AND (did_operation IS NOT NULL)))),
    CONSTRAINT identity_creation_leases_registry_complete CHECK ((((state = ANY (ARRAY['active'::text, 'reserved'::text])) AND (registry_receipt IS NULL) AND (head_event_digest IS NULL)) OR ((state = ANY (ARRAY['did_published'::text, 'pcr_accepted'::text, 'account_bound'::text, 'completed'::text])) AND (registry_receipt IS NOT NULL) AND (jsonb_typeof(registry_receipt) = 'object'::text) AND (head_event_digest IS NOT NULL)))),
    CONSTRAINT identity_creation_leases_pcr_complete CHECK ((((state = ANY (ARRAY['active'::text, 'reserved'::text, 'did_published'::text])) AND (pcr_genesis_request_digest IS NULL) AND (pcr_genesis_receipt IS NULL)) OR ((state = ANY (ARRAY['pcr_accepted'::text, 'account_bound'::text, 'completed'::text])) AND (pcr_genesis_request_digest IS NOT NULL) AND (pcr_genesis_receipt IS NOT NULL)))),
    CONSTRAINT identity_creation_leases_binding_complete CHECK ((((state <> ALL (ARRAY['account_bound'::text, 'completed'::text])) AND (binding_receipt IS NULL)) OR ((state = ANY (ARRAY['account_bound'::text, 'completed'::text])) AND (binding_receipt IS NOT NULL)))),
    CONSTRAINT identity_creation_leases_register_ledger_complete CHECK ((((state <> 'completed'::text) AND (register_handoff_grant_id IS NULL) AND (register_challenge_id IS NULL) AND (register_request_digest IS NULL) AND (register_outcome IS NULL)) OR ((state = 'completed'::text) AND (register_handoff_grant_id IS NOT NULL) AND (register_challenge_id IS NOT NULL) AND (register_request_digest IS NOT NULL) AND (register_outcome IS NOT NULL))))
);

-- Durable, append-only quota consumption.  The subject is the service's
-- salted account-subject digest, never the raw upstream OIDC `sub`.
CREATE TABLE public.identity_creation_lease_rate_limit_events (
    id bigserial NOT NULL,
    request_id uuid NOT NULL,
    account_subject text NOT NULL,
    audience_id text NOT NULL,
    lease_id text NOT NULL,
    action text NOT NULL,
    occurred_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT identity_creation_lease_rate_subject_valid CHECK ((account_subject ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_creation_lease_rate_audience_id_nonempty CHECK ((btrim(audience_id) <> ''::text)),
    CONSTRAINT identity_creation_lease_rate_lease_id_valid CHECK ((lease_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_creation_lease_rate_action_closed CHECK ((action = ANY (ARRAY['acquisition'::text, 'renewal'::text])))
);

CREATE TABLE public.identity_binding_challenges (
    request_id uuid NOT NULL,
    request_digest text NOT NULL,
    local_account_id uuid NOT NULL,
    challenge_id text NOT NULL,
    challenge text NOT NULL,
    purpose text NOT NULL,
    account_subject text NOT NULL,
    principal_id text NOT NULL,
    did text NOT NULL,
    operation_digest text NOT NULL,
    did_version_id text NOT NULL,
    log_head_digest text NOT NULL,
    control_key_digest text NOT NULL,
    pcr_realm_id text NOT NULL,
    realm_create_payload_digest text NOT NULL,
    founding_authorize_payload_digest text NOT NULL,
    initial_session_request_digest text NOT NULL,
    lease_id text NOT NULL,
    lease_fence bigint NOT NULL,
    dpop_jkt text NOT NULL,
    audience_id text NOT NULL,
    origin text NOT NULL,
    trust_domain text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    replaced_at timestamp with time zone,
    CONSTRAINT identity_binding_challenges_request_digest_valid CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_challenge_id_valid CHECK ((challenge_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_binding_challenges_challenge_nonempty CHECK ((length(challenge) >= 22)),
    CONSTRAINT identity_binding_challenges_purpose_valid CHECK ((purpose = 'account_binding_and_pcr_genesis'::text)),
    CONSTRAINT identity_binding_challenges_operation_digest_valid CHECK ((operation_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_account_subject_valid CHECK ((account_subject ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_principal_core_valid CHECK ((principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT identity_binding_challenges_did_bare CHECK ((did ~ '^did:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT identity_binding_challenges_did_version_nonempty CHECK ((btrim(did_version_id) <> ''::text)),
    CONSTRAINT identity_binding_challenges_log_head_digest_valid CHECK ((log_head_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_control_key_digest_valid CHECK ((control_key_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_pcr_realm_id_nonempty CHECK ((btrim(pcr_realm_id) <> ''::text)),
    CONSTRAINT identity_binding_challenges_realm_create_digest_valid CHECK ((realm_create_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_founding_authorize_digest_valid CHECK ((founding_authorize_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_initial_session_digest_valid CHECK ((initial_session_request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_binding_challenges_lease_id_valid CHECK ((lease_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_binding_challenges_lease_fence_positive CHECK ((lease_fence >= 1)),
    CONSTRAINT identity_binding_challenges_dpop_jkt_valid CHECK ((dpop_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT identity_binding_challenges_expiry_valid CHECK ((expires_at > issued_at AND expires_at <= (issued_at + '00:05:00'::interval)))
);

CREATE TABLE public.did_binding_challenges (
    request_id uuid PRIMARY KEY,
    request_digest text NOT NULL,
    issuing_handoff_grant_id uuid NOT NULL,
    local_account_id uuid NOT NULL,
    account_subject text NOT NULL,
    principal_id text NOT NULL,
    did text NOT NULL,
    did_version_id text NOT NULL,
    log_head_digest text NOT NULL,
    control_key_digest text NOT NULL,
    witness_evidence text,
    challenge_id text NOT NULL UNIQUE,
    challenge text NOT NULL,
    dpop_jkt text NOT NULL,
    audience_id text NOT NULL,
    origin text NOT NULL,
    trust_domain text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    register_request_digest text,
    register_outcome jsonb,
    CONSTRAINT did_binding_challenges_request_digest_valid CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT did_binding_challenges_account_subject_valid CHECK ((account_subject ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT did_binding_challenges_principal_core_valid CHECK ((principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT did_binding_challenges_did_bare CHECK ((did ~ '^did:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT did_binding_challenges_version_nonempty CHECK ((btrim(did_version_id) <> ''::text)),
    CONSTRAINT did_binding_challenges_log_head_valid CHECK ((log_head_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT did_binding_challenges_control_key_valid CHECK ((control_key_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT did_binding_challenges_challenge_id_valid CHECK ((challenge_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT did_binding_challenges_challenge_nonempty CHECK ((length(challenge) >= 22)),
    CONSTRAINT did_binding_challenges_dpop_jkt_valid CHECK ((dpop_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT did_binding_challenges_expiry_valid CHECK ((expires_at > issued_at AND expires_at <= (issued_at + '00:05:00'::interval))),
    CONSTRAINT did_binding_challenges_register_complete CHECK (((register_request_digest IS NULL AND register_outcome IS NULL) OR (consumed_at IS NOT NULL AND register_request_digest ~ '^sha256:[0-9a-f]{64}$'::text AND jsonb_typeof(register_outcome) = 'object'::text)))
);

-- Durable explicit-abandonment transcript. The challenge retains both the
-- issuing handoff and its holder key so confirmation can require a different
-- freshly authenticated handoff without weakening the holder binding.
CREATE TABLE public.identity_abandonment_challenges (
    request_id uuid PRIMARY KEY,
    request_digest text NOT NULL,
    issuing_handoff_grant_id uuid NOT NULL,
    local_account_id uuid NOT NULL,
    audience_id text NOT NULL,
    account_subject text NOT NULL,
    holder_jkt text NOT NULL,
    lease_id text NOT NULL,
    lease_fence bigint NOT NULL,
    principal_id text NOT NULL,
    did_version_id text NOT NULL,
    challenge_id text NOT NULL UNIQUE,
    challenge text NOT NULL,
    origin text NOT NULL,
    trust_domain text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    confirmation_request_id uuid UNIQUE,
    confirmation_request_digest text,
    outcome jsonb,
    CONSTRAINT identity_abandonment_principal_core_valid CHECK ((principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT identity_abandonment_request_digest_valid CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_abandonment_account_subject_valid CHECK ((account_subject ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_abandonment_holder_jkt_valid CHECK ((holder_jkt ~ '^[A-Za-z0-9_-]{43}$'::text)),
    CONSTRAINT identity_abandonment_lease_id_valid CHECK ((lease_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_abandonment_lease_fence_positive CHECK ((lease_fence >= 1)),
    CONSTRAINT identity_abandonment_did_version_nonempty CHECK ((btrim(did_version_id) <> ''::text)),
    CONSTRAINT identity_abandonment_challenge_id_valid CHECK ((challenge_id ~ '^[A-Za-z0-9_-]{22,128}$'::text)),
    CONSTRAINT identity_abandonment_challenge_nonempty CHECK ((length(challenge) >= 22)),
    CONSTRAINT identity_abandonment_expiry_valid CHECK ((expires_at > issued_at AND expires_at <= (issued_at + '00:05:00'::interval))),
    CONSTRAINT identity_abandonment_confirmation_shape CHECK (((consumed_at IS NULL AND confirmation_request_id IS NULL AND confirmation_request_digest IS NULL AND outcome IS NULL) OR (consumed_at IS NOT NULL AND confirmation_request_id IS NOT NULL AND confirmation_request_digest IS NOT NULL AND confirmation_request_digest ~ '^sha256:[0-9a-f]{64}$'::text AND outcome IS NOT NULL AND jsonb_typeof(outcome) = 'object'::text)))
);

-- Append-only reservation preventing a published entry-0 orphan anchor from
-- ever being reused as a live identity root.
CREATE TABLE public.identity_orphan_anchor_tombstones (
    principal_id text PRIMARY KEY,
    did_version_id text NOT NULL,
    account_subject text NOT NULL,
    abandonment_request_id uuid NOT NULL UNIQUE,
    abandoned_at timestamp with time zone NOT NULL,
    CONSTRAINT identity_orphan_anchor_principal_core_valid CHECK ((principal_id ~ '^ak:did_core:[a-z0-9]+:[^[:space:]/?#]+$'::text)),
    CONSTRAINT identity_orphan_anchor_version_nonempty CHECK ((btrim(did_version_id) <> ''::text)),
    CONSTRAINT identity_orphan_anchor_account_subject_valid CHECK ((account_subject ~ '^sha256:[0-9a-f]{64}$'::text))
);

CREATE TABLE public.queue_jobs (
    id uuid NOT NULL,
    status text DEFAULT 'available'::text NOT NULL,
    started_at timestamp with time zone,
    started_by uuid,
    completed_at timestamp with time zone,
    queue_name text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    failed_at timestamp with time zone,
    failed_reason text,
    attempt integer DEFAULT 0 NOT NULL,
    next_attempt_id uuid,
    scheduled_at timestamp with time zone,
    schedule_name text,
    created_at timestamp with time zone NOT NULL
);

CREATE UNLOGGED TABLE public.queue_leader (
    active boolean DEFAULT true NOT NULL,
    elected_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    queue_worker_id uuid NOT NULL
);

CREATE TABLE public.queue_schedules (
    schedule_name text NOT NULL,
    last_scheduled_at timestamp with time zone,
    last_scheduled_job_id uuid
);

CREATE TABLE public.queue_workers (
    id uuid NOT NULL,
    registered_at timestamp with time zone NOT NULL,
    last_seen_at timestamp with time zone NOT NULL,
    shutdown_at timestamp with time zone
);

CREATE TABLE public.risk_action_proposals (
    id uuid NOT NULL,
    account_id uuid NOT NULL,
    action text NOT NULL,
    proposer_id text NOT NULL,
    reason text NOT NULL,
    ticket text,
    state text DEFAULT 'draft'::text NOT NULL,
    approval_proofs jsonb DEFAULT '[]'::jsonb NOT NULL,
    required_approvals integer NOT NULL,
    approved_at timestamp with time zone,
    executed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT risk_action_proposals_action_non_empty CHECK ((btrim(action) <> ''::text)),
    CONSTRAINT risk_action_proposals_proposer_id_format CHECK ((proposer_id ~ '^ak:did_core:[A-Za-z0-9._:%-]+$'::text)),
    CONSTRAINT risk_action_proposals_reason_non_empty CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT risk_action_proposals_required_approvals_positive CHECK ((required_approvals >= 1)),
    CONSTRAINT risk_action_proposals_state_valid CHECK ((state = ANY (ARRAY['draft'::text, 'approved'::text, 'executed'::text, 'cancelled'::text, 'rejected'::text])))
);

CREATE TABLE public.station_trust_enrollments (
    name text NOT NULL,
    canonical_endpoint text NOT NULL,
    service_id text NOT NULL,
    service_kind text NOT NULL,
    did text NOT NULL,
    method_history_head text NOT NULL,
    version_id text NOT NULL,
    resolution_record_digest text NOT NULL,
    source text NOT NULL,
    enrolled_at timestamp with time zone DEFAULT now() NOT NULL,
    last_verified_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT station_trust_enrollments_name_non_empty CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT station_trust_enrollments_canonical_endpoint_non_empty CHECK ((btrim(canonical_endpoint) <> ''::text)),
    CONSTRAINT station_trust_enrollments_service_id_non_empty CHECK ((btrim(service_id) <> ''::text)),
    CONSTRAINT station_trust_enrollments_service_kind_valid CHECK ((service_kind = 'station'::text)),
    CONSTRAINT station_trust_enrollments_did_non_empty CHECK ((btrim(did) <> ''::text)),
    CONSTRAINT station_trust_enrollments_method_history_head_non_empty CHECK ((btrim(method_history_head) <> ''::text)),
    CONSTRAINT station_trust_enrollments_version_id_non_empty CHECK ((btrim(version_id) <> ''::text)),
    CONSTRAINT station_trust_enrollments_resolution_record_digest_non_empty CHECK ((btrim(resolution_record_digest) <> ''::text)),
    CONSTRAINT station_trust_enrollments_source_valid CHECK ((source = ANY (ARRAY['operator_cli'::text, 'deployment_artifact'::text, 'development_auto'::text])))
);

COMMENT ON TABLE public.station_trust_enrollments IS 'Deployment-local station trust enrollment: the accepted authorization pin per canonical endpoint, written only by explicit bootstrap/replace or the narrowly-scoped development auto-enrollment.';

CREATE TABLE public.station_trust_audits (
    id uuid NOT NULL,
    enrollment_name text NOT NULL,
    action text NOT NULL,
    service_id text,
    previous_service_id text,
    detail text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT station_trust_audits_action_valid CHECK ((action = ANY (ARRAY['enrolled'::text, 'verification_failed'::text, 'replaced'::text, 'revoked'::text])))
);

COMMENT ON TABLE public.station_trust_audits IS 'Append-only audit log covering station trust enrollment creation, verification failures, explicit replacement and revocation.';

